function solve({config,state,event}){
  let s=state||{now:0,jobs:[],next:0}, now=s.now, jobs=s.jobs.slice(), next=s.next||0;
  const expire=()=>{jobs=jobs.filter(j=>j.deadline>now)};
  expire();
  let status,ran=null;
  if(event.type==='add'){
    let bytes=jobs.reduce((a,j)=>a+j.size,0);
    if(jobs.some(j=>j.id===event.id)||event.deadline<=now||bytes+event.size>config.capacity)status='rejected';
    else{jobs.push({id:event.id,size:event.size,deadline:event.deadline,seq:next++});status='accepted'}
  }else if(event.type==='cancel'){
    let k=jobs.findIndex(j=>j.id===event.id);
    if(k<0)status='missing';else{jobs.splice(k,1);status='cancelled'}
  }else if(event.type==='advance'){
    now+=event.dt;expire();status='advanced'
  }else{
    if(!jobs.length)status='empty';
    else{let k=0;for(let i=1;i<jobs.length;i++)if(jobs[i].deadline<jobs[k].deadline||jobs[i].deadline===jobs[k].deadline&&jobs[i].seq<jobs[k].seq)k=i;ran=jobs[k].id;jobs.splice(k,1);status='ran'}
  }
  let bytes=jobs.reduce((a,j)=>a+j.size,0);
  return {state:{now:now,jobs:jobs,next:next},output:{status:status,ran:ran,pending:jobs.map(j=>j.id),bytes:bytes,now:now}};
}
